// Свободные слоты — переходник CRM по рабочему календарю и Записям (нет календаря — calendar false).
const ctx = $('Load context').item.json;
const calendar = $json;
const knowledge = $('Load knowledge base').item.json.list.map(({ kind, name, description, price, priceFrom }) => ({ kind, name, description, price, priceFrom }));
// Поля Заявки; обязательные из них выбирает Заказчик (companies.required_fields, миграция 0011).
